{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the travel speed (or the travel-time formula) between two points, so I can convert the Euclidean distance between coordinates into minutes for the time-window constraints?"
  ],
  "rationale": "The response asks for a single piece of information: the travel speed or formula needed to convert distance to time."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Should the objective minimize the total Euclidean distance traveled (in coordinate units), or the total travel time in minutes?"
  ],
  "rationale": "The response asks for a single policy choice between two specific objective functions, which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Do all trucks have to start at the depot and return to the depot at the end of their route, or is it acceptable for a truck to finish its route at the last customer it serves?"
  ],
  "rationale": "The response asks for a single policy choice regarding truck route endpoints (depot return vs. open route), which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can a single truck serve multiple customers in one route (visiting several customers before returning to the depot), or is each truck limited to serving exactly one customer per trip?"
  ],
  "rationale": "The response asks for a single policy choice regarding truck capacity per trip, presented as a binary alternative."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can a truck make more than one round trip (depot → customers → depot → customers → depot) within the operating day, or does each truck make at most one trip out of the depot?"
  ],
  "rationale": "The response asks a single clarification question regarding the maximum number of trips a truck can make, presented as a binary choice."
}

{
  "action": "question",
  "question_count": 2,
  "is_atomic": false,
  "atomic_questions": [
    "Is the travel time between two points computed as the Euclidean distance divided by a constant speed (i.e., travel time = distance / speed)?",
    "What is that speed in coordinate-units per minute?"
  ],
  "rationale": "The response asks whether a specific formula is used and, conditionally, for the value of the speed parameter. These are two semantically independent requests: the first is a yes/no confirmation of the method, and the second is a request for a specific numerical value."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the truck capacity of 200 units a per-route limit (the sum of demands of all customers visited on one truck's route must not exceed 200), or is it a per-trip limit that resets each time the truck returns to the depot?"
  ],
  "rationale": "The response asks for a single policy choice between two mutually exclusive interpretations of the capacity constraint."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Do all 20 customers have to be served within the depot's operating window of [0, 1236] minutes, meaning every truck must complete its route and be back at the depot by minute 1236?"
  ],
  "rationale": "The response contains a single clarification question asking for confirmation of the time window constraint for all customers and trucks."
}

